srcDoc.css:
body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: transparent;
  color: #111827;
}

.pulse {
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  padding: 18px;
  background: #f8fafc;
}

.pulse-hero {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 22px;
  padding: 22px;
  background: #111827;
  color: white;
  border-radius: 10px;
}

.eyebrow {
  color: #5eead4;
  font-size: 12px;
  font-weight: 900;
  text-transform: uppercase;
}

h1 {
  margin: 6px 0 4px;
  font-size: 34px;
  line-height: 1;
}

p {
  margin: 0;
  color: #cbd5e1;
}

.score-ring {
  width: 128px;
  height: 128px;
  position: relative;
  flex: 0 0 auto;
}

.score-ring svg {
  width: 128px;
  height: 128px;
  transform: rotate(-90deg);
}

.track,
.arc {
  fill: none;
  stroke-width: 10;
}

.track {
  stroke: rgba(255, 255, 255, 0.18);
}

.arc {
  stroke: #14b8a6;
  stroke-linecap: round;
  stroke-dasharray: 314;
  stroke-dashoffset: 314;
  transition: stroke-dashoffset 0.5s ease;
}

.score-value {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  text-align: center;
}

.score-value strong {
  display: block;
  font-size: 31px;
  line-height: 1;
}

.score-value span {
  display: block;
  margin-top: 4px;
  color: #cbd5e1;
  font-size: 11px;
  text-transform: uppercase;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-top: 14px;
}

.metric,
.panel,
.delta {
  background: white;
  border: 1px solid #e5e7eb;
  border-radius: 10px;
}

.metric {
  padding: 14px;
}

.metric span,
.panel-head span,
.delta span {
  display: block;
  color: #64748b;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.metric strong {
  display: block;
  margin-top: 8px;
  font-size: 23px;
}

.metric.danger strong {
  color: #dc2626;
}

.metric.warning strong {
  color: #d97706;
}

.main-grid {
  display: grid;
  grid-template-columns: 1.25fr 0.75fr;
  gap: 14px;
  margin-top: 14px;
}

.panel {
  padding: 16px;
  min-height: 260px;
}

.panel-head {
  display: flex;
  justify-content: space-between;
  margin-bottom: 12px;
}

.panel-head h2 {
  margin: 4px 0 0;
  font-size: 18px;
}

.actions {
  display: grid;
  gap: 10px;
}

.action {
  display: grid;
  grid-template-columns: 10px 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 12px;
  border: 1px solid #e5e7eb;
  border-radius: 8px;
  cursor: pointer;
  background: #fff;
}

.action:hover {
  border-color: #14b8a6;
  background: #f0fdfa;
}

.dot {
  width: 10px;
  height: 42px;
  border-radius: 999px;
  background: #64748b;
}

.action.danger .dot {
  background: #ef4444;
}

.action.warning .dot {
  background: #f59e0b;
}

.action.info .dot {
  background: #0ea5e9;
}

.action-title {
  font-weight: 900;
}

.action-detail {
  margin-top: 3px;
  color: #64748b;
  font-size: 12px;
}

.action-count {
  min-width: 34px;
  height: 34px;
  border-radius: 8px;
  background: #111827;
  color: white;
  display: grid;
  place-items: center;
  font-weight: 900;
}

.empty {
  padding: 22px;
  text-align: center;
  color: #64748b;
  border: 1px dashed #cbd5e1;
  border-radius: 8px;
}

.flow {
  display: grid;
  gap: 12px;
}

.flow-row {
  display: grid;
  grid-template-columns: 1fr 44px;
  gap: 10px;
  align-items: center;
}

.flow-label {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 800;
}

.bar {
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: #e5e7eb;
}

.bar > div {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, #2563eb, #14b8a6);
}

.flow-count {
  text-align: right;
  font-weight: 900;
}

.delta {
  display: grid;
  grid-template-columns: repeat(3, 1fr) auto;
  gap: 14px;
  align-items: center;
  margin-top: 14px;
  padding: 14px;
}

.delta strong {
  display: block;
  margin-top: 4px;
  font-size: 18px;
}

.delta small {
  color: #64748b;
  text-align: right;
}

@media (max-width: 900px) {
  .metrics,
  .main-grid,
  .delta {
    grid-template-columns: 1fr;
  }
  .pulse-hero {
    align-items: flex-start;
  }
}

