function money(value) {
  return Number(value || 0).toFixed(2);
}
function num(value) {
  return Number(value || 0);
}
function setText(id, value) {
  const el = document.getElementById(id);
  if (el) el.innerText = value;
}
function actionClass(severity) {
  return ["danger", "warning", "info"].includes(severity) ? severity : "info";
}
function openAction(actionCode) {
  appsmith.updateModel({
    selectedPulseAction: actionCode
  });
  appsmith.triggerEvent("onPulseAction");
}
function renderActions(actions) {
  const root = document.getElementById("actions");
  if (!root) return;
  if (!actions.length) {
    root.innerHTML = `<div class="empty">Everything looks clean. No urgent action right now.</div>`;
    return;
  }
  root.innerHTML = actions.map(action => `
    <div class="action ${actionClass(action.severity)}" data-action="${action.actionCode}">
      <div class="dot"></div>
      <div>
        <div class="action-title">${action.title || ""}</div>
        <div class="action-detail">${action.detail || ""}</div>
      </div>
      <div class="action-count">${action.countValue || 0}</div>
    </div>
  `).join("");
  root.querySelectorAll(".action").forEach(el => {
    el.onclick = () => openAction(el.dataset.action);
  });
}
function renderFlow(flow) {
  const root = document.getElementById("flow");
  if (!root) return;
  if (!flow.length) {
    root.innerHTML = `<div class="empty">No active operational flow.</div>`;
    return;
  }
  const max = Math.max(...flow.map(row => num(row.countValue)), 1);
  root.innerHTML = flow.map(row => {
    const count = num(row.countValue);
    const width = Math.max(4, Math.round(count / max * 100));
    return `
      <div class="flow-row">
        <div>
          <div class="flow-label">
            <span>${row.stepLabel || ""}</span>
          </div>
          <div class="bar"><div style="width:${width}%"></div></div>
        </div>
        <div class="flow-count">${count}</div>
      </div>
    `;
  }).join("");
}
function render(model = {}) {
  const score = model.score || {};
  const delta = model.delta || {};
  const health = Math.max(0, Math.min(100, num(score.healthScore)));
  setText("healthScore", Math.round(health));
  setText("todaySales", money(score.todaySales));
  setText("todayDocuments", num(score.todayDocuments));
  setText("fiscalIssues", num(score.fiscalIssues));
  setText("lowStockItems", num(score.lowStockItems));
  setText("salesDelta", money(delta.salesDelta));
  setText("documentDelta", num(delta.documentDelta));
  setText("taskDelta", num(delta.taskDelta));
  setText("generatedAt", "Updated: " + (model.generatedAt || ""));
  const arc = document.getElementById("scoreArc");
  if (arc) {
    const circumference = 314;
    arc.style.strokeDashoffset = String(circumference - circumference * health / 100);
    if (health < 55) arc.style.stroke = "#ef4444";else if (health < 75) arc.style.stroke = "#f59e0b";else arc.style.stroke = "#14b8a6";
  }
  renderActions(model.actions || []);
  renderFlow(model.flow || []);
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

